const DB = "processalpha", STORE = "trades", PLANS_STORE = "plans", RULES_KEY = "processalpha-rules-v1", POLICY_KEY = "processalpha-agent-policy-v1";
const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
let trades = [], plans = [], rules = loadRules(), agentPolicy = loadPolicy(), selectedId = null, selectedPlanId = null, cloudClient = null, cloudSession = null;
const reviewCache = new Map();
function track(event, details = {}) { fetch("/api/event", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ event, ...details }), keepalive: true }).catch(() => {}); }

function escapeHtml(value) { return String(value ?? "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]); }
function openDB() { return new Promise((resolve, reject) => { const request = indexedDB.open(DB, 2); request.onupgradeneeded = () => { if (!request.result.objectStoreNames.contains(STORE)) request.result.createObjectStore(STORE, { keyPath: "id" }); if (!request.result.objectStoreNames.contains(PLANS_STORE)) request.result.createObjectStore(PLANS_STORE, { keyPath: "id" }); }; request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); }
async function readAll() { const db = await openDB(); return new Promise((resolve, reject) => { const request = db.transaction(STORE).objectStore(STORE).getAll(); request.onsuccess = () => resolve(request.result.sort((a, b) => b.created - a.created)); request.onerror = () => reject(request.error); }); }
async function localPut(value) { const db = await openDB(); return new Promise((resolve, reject) => { const request = db.transaction(STORE, "readwrite").objectStore(STORE).put(value); request.onsuccess = resolve; request.onerror = () => reject(request.error); }); }
async function localDelete(id) { const db = await openDB(); return new Promise((resolve, reject) => { const request = db.transaction(STORE, "readwrite").objectStore(STORE).delete(id); request.onsuccess = resolve; request.onerror = () => reject(request.error); }); }
async function readPlans() { const db = await openDB(); return new Promise((resolve, reject) => { const request = db.transaction(PLANS_STORE).objectStore(PLANS_STORE).getAll(); request.onsuccess = () => resolve(request.result.sort((a, b) => b.created - a.created)); request.onerror = () => reject(request.error); }); }
async function localPlanPut(value) { const db = await openDB(); return new Promise((resolve, reject) => { const request = db.transaction(PLANS_STORE, "readwrite").objectStore(PLANS_STORE).put(value); request.onsuccess = resolve; request.onerror = () => reject(request.error); }); }
function toCloudPlan(plan, userId) { return { id: plan.id, user_id: userId, symbol: plan.symbol, side: plan.side, planned_entry: plan.plannedEntry, stop_price: plan.stopPrice, target_price: plan.targetPrice, risk_percent: plan.riskPercent, thesis: plan.thesis, invalidation: plan.invalidation, rule_ids: plan.ruleIds, status: plan.status, executed_at: plan.executedAt ? new Date(plan.executedAt).toISOString() : null, completed_at: plan.completedAt ? new Date(plan.completedAt).toISOString() : null, trade_id: plan.tradeId || null, receipt: plan.receipt || null, created_at: new Date(plan.created).toISOString(), updated_at: new Date().toISOString() }; }
function fromCloudPlan(plan) { return { id: plan.id, created: new Date(plan.created_at).getTime(), symbol: plan.symbol, side: plan.side, plannedEntry: Number(plan.planned_entry), stopPrice: Number(plan.stop_price), targetPrice: Number(plan.target_price), riskPercent: Number(plan.risk_percent), thesis: plan.thesis, invalidation: plan.invalidation, ruleIds: Array.isArray(plan.rule_ids) ? plan.rule_ids : [], status: plan.status, executedAt: plan.executed_at ? new Date(plan.executed_at).getTime() : null, completedAt: plan.completed_at ? new Date(plan.completed_at).getTime() : null, tradeId: plan.trade_id || null, receipt: plan.receipt || null }; }
async function savePlan(value) { await localPlanPut(value); if (cloudClient && cloudSession) { const { error } = await cloudClient.from("trade_plans").upsert(toCloudPlan(value, cloudSession.user.id)); if (error) throw error; } }
async function saveTrade(value) { await localPut(value); if (cloudClient && cloudSession) { const { error } = await cloudClient.from("trades").upsert(toCloud(value, cloudSession.user.id)); if (error) throw error; } }
function score(trade) { return [trade.risk, trade.evidence, trade.confirm, trade.followed].filter(Boolean).length * 25; }
function pnl(trade) { const raw = (trade.exit - trade.entry) / trade.entry * 100; return trade.side === "Short" ? -raw : raw; }
function verdict(trade) { const disciplined = score(trade) >= 75, won = pnl(trade) > 0; return disciplined ? (won ? "Good decision, good outcome" : "Good decision, adverse outcome") : (won ? "Weak decision, favorable outcome" : "Weak decision, adverse outcome"); }
function rate(key) { return trades.length ? Math.round(trades.filter(trade => trade[key]).length / trades.length * 100) : 0; }

function renderPlanRuleOptions() {
  $("#planRules").innerHTML = rules.length ? rules.map(rule => `<label class="check"><input type="checkbox" name="playbookRule" value="${escapeHtml(rule.id)}"><span><b>Attach rule</b>${escapeHtml(rule.text)}</span></label>`).join("") : '<p class="note">No playbook rules yet. You can still create a plan, or add rules in Playbook first.</p>';
}
function planStatus(plan) { return plan.status === "completed" ? "Audited" : plan.status === "open" ? "Paper position open" : "Locked / awaiting approval"; }
function renderPlans() {
  renderPlanRuleOptions();
  $("#planCount").textContent = `${plans.length} ${plans.length === 1 ? "plan" : "plans"}`;
  if (!plans.length) { $("#planList").innerHTML = '<div class="empty"><div><b>No plans yet</b>Lock a pre-trade plan before executing your next setup.</div></div>'; $("#planDetail").hidden = true; $("#paperChartCard").hidden = true; return; }
  $("#planList").innerHTML = `<div class="list">${plans.map(plan => `<article class="trade ${plan.id === selectedPlanId ? "selected" : ""}" data-plan-id="${escapeHtml(plan.id)}"><div><b>${escapeHtml(plan.symbol)} / ${escapeHtml(plan.side)}</b><div class="meta">${new Date(plan.created).toLocaleString()} / ${escapeHtml(planStatus(plan))}</div></div><div class="statuspill">${plan.status === "planned" ? "LOCKED" : plan.status.toUpperCase()}</div></article>`).join("")}</div>`;
  $("#planList").onclick = event => { const item = event.target.closest("[data-plan-id]"); if (item) selectPlan(item.dataset.planId); };
  selectPlan(selectedPlanId && plans.some(plan => plan.id === selectedPlanId) ? selectedPlanId : plans[0].id);
}
function selectPlan(id) {
  selectedPlanId = id; const plan = plans.find(item => item.id === id); if (!plan) return;
  $$('[data-plan-id]').forEach(item => item.classList.toggle("selected", item.dataset.planId === id));
  const attached = plan.ruleIds.map(ruleId => rules.find(rule => rule.id === ruleId)?.text).filter(Boolean);
  const action = plan.status === "planned" ? '<p id="orderPreview" class="note">Loading live Bitget quote for dry-run preview.</p><button class="button full" id="approvePaper" type="button">Preview and approve paper order</button>' : plan.status === "open" ? '<button class="button full" id="completeAudit" type="button">Complete and audit trade</button>' : '<p class="good"><b>Audit complete</b></p>';
  $("#planDetail").hidden = false;
  $("#planDetail").innerHTML = `<article><h3>Frozen thesis</h3><blockquote>“${escapeHtml(plan.thesis)}”</blockquote><p class="note">Invalidation: ${escapeHtml(plan.invalidation)}</p></article><article><h3>Planned execution</h3><p><b>${escapeHtml(plan.symbol)} / ${escapeHtml(plan.side)}</b></p><p>Entry ${plan.plannedEntry} / Stop ${plan.stopPrice} / Target ${plan.targetPrice}</p><p class="note">Maximum account risk: ${plan.riskPercent}%</p></article><article><h3>Attached playbook</h3><p>${attached.length ? attached.map(escapeHtml).join(" / ") : "No rules attached"}</p><p class="note">Locked ${new Date(plan.created).toLocaleString()}</p></article><article class="signal"><h3>${escapeHtml(planStatus(plan))}</h3><p>This paper workflow never places a live order or uses funds.</p>${action}</article>`;
  $("#paperChartCard").hidden = false; renderPaperChart(plan);
  const approve = $("#approvePaper"); if (approve) { loadOrderPreview(plan); approve.onclick = async () => { if (agentPolicy.mode === "readonly") return alert("Read-only mode blocks execution."); if (agentPolicy.mode === "live") return alert("Live mode is blocked until Bitget Agentic Account OAuth is connected. Use paper mode now."); approve.disabled = true; try { const market = await getMarketQuote(plan.symbol); const riskAmount = agentPolicy.maxCapital * plan.riskPercent / 100; if (riskAmount > agentPolicy.dailyLoss) throw new Error("This plan exceeds the daily loss limit."); plan.status = "open"; plan.executedAt = Date.now(); plan.receipt = { id: crypto.randomUUID(), created: plan.executedAt, mode: "paper", status: "filled", source: market.source, symbol: plan.symbol, side: plan.side, plannedEntry: plan.plannedEntry, marketPrice: market.lastPrice, notional: Math.min(agentPolicy.maxOrder, agentPolicy.maxCapital), maximumRisk: riskAmount, leverage: agentPolicy.maxLeverage, humanConfirmed: true }; await savePlan(plan); plans = await readPlans(); renderAll(); track("paper_execution_approved"); } catch (error) { alert(error.message || "Paper execution could not be approved."); } finally { approve.disabled = false; } }; }
  const complete = $("#completeAudit"); if (complete) complete.onclick = () => beginAudit(plan);
}
function showView(name) { $$('[data-view]').forEach(item => item.classList.toggle("active", item.dataset.view === name)); $$(".view").forEach(view => view.classList.toggle("active", view.id === `${name}View`)); }
function beginAudit(plan) {
  showView("journal"); const form = $("#form");
  form.elements.planId.value = plan.id; form.elements.symbol.value = plan.symbol; form.elements.side.value = plan.side; form.elements.entry.value = plan.plannedEntry; form.elements.thesis.value = plan.thesis; form.elements.invalidation.value = plan.invalidation;
  $("#formError").textContent = "Complete the actual exit and confirm which commitments were followed. The original plan remains locked.";
  form.scrollIntoView({ behavior: "smooth", block: "start" });
}
async function getMarketQuote(symbol) { const response = await fetch(`/api/market?symbol=${encodeURIComponent(symbol)}`); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Market validation unavailable"); return data; }
async function loadOrderPreview(plan) { try { const market = await getMarketQuote(plan.symbol), slippage = Math.abs((market.lastPrice - plan.plannedEntry) / plan.plannedEntry * 100); const preview = $("#orderPreview"); if (preview && selectedPlanId === plan.id) preview.textContent = `Dry run: ${plan.side} ${plan.symbol} near ${market.lastPrice}. Planned ${plan.plannedEntry}. Deviation ${slippage.toFixed(2)}%. Maximum notional ${Math.min(agentPolicy.maxOrder, agentPolicy.maxCapital)} USDT.`; } catch { const preview = $("#orderPreview"); if (preview) preview.textContent = "Live quote unavailable. Execution remains blocked until validation succeeds."; } }

function chartNumber(value) { return Number(value).toLocaleString(undefined, { maximumFractionDigits: Number(value) >= 100 ? 2 : 6 }); }
async function renderPaperChart(plan) {
  const target = $("#paperChart"), summary = $("#paperPosition");
  target.innerHTML = '<div class="chartloading">Loading live candles...</div>'; summary.innerHTML = "";
  try {
    const response = await fetch(`/api/candles?symbol=${encodeURIComponent(plan.symbol)}&interval=15m`), data = await response.json();
    if (!response.ok || !data.candles?.length) throw new Error(data.error || "Chart data unavailable");
    if (selectedPlanId !== plan.id) return;
    const candles = data.candles, width = Math.max(720, target.clientWidth || 1000), height = 390, pad = { top: 22, right: 94, bottom: 34, left: 14 };
    const levels = [plan.plannedEntry, plan.stopPrice, plan.targetPrice, plan.receipt?.marketPrice, plan.receipt?.exitPrice].filter(Number.isFinite);
    let low = Math.min(...candles.map(candle => candle.low), ...levels), high = Math.max(...candles.map(candle => candle.high), ...levels); const range = high - low || 1; low -= range * .06; high += range * .06;
    const plotWidth = width - pad.left - pad.right, plotHeight = height - pad.top - pad.bottom, x = index => pad.left + (index + .5) * plotWidth / candles.length, y = price => pad.top + (high - price) / (high - low) * plotHeight, bodyWidth = Math.max(2, plotWidth / candles.length * .62);
    const grid = Array.from({ length: 5 }, (_, index) => { const price = high - (high - low) * index / 4, py = y(price); return `<line x1="${pad.left}" y1="${py}" x2="${width - pad.right}" y2="${py}" class="chartgrid"/><text x="${width - pad.right + 8}" y="${py + 4}" class="chartaxis">${chartNumber(price)}</text>`; }).join("");
    const bars = candles.map((candle, index) => { const up = candle.close >= candle.open, color = up ? "#155f46" : "#a83d35", top = Math.min(y(candle.open), y(candle.close)), bodyHeight = Math.max(1.5, Math.abs(y(candle.open) - y(candle.close))); return `<line x1="${x(index)}" y1="${y(candle.high)}" x2="${x(index)}" y2="${y(candle.low)}" stroke="${color}"/><rect x="${x(index) - bodyWidth / 2}" y="${top}" width="${bodyWidth}" height="${bodyHeight}" fill="${color}"/>`; }).join("");
    const line = (price, label, color, dash = "") => `<line x1="${pad.left}" y1="${y(price)}" x2="${width - pad.right}" y2="${y(price)}" stroke="${color}" stroke-width="1.5" ${dash ? `stroke-dasharray="${dash}"` : ""}/><rect x="${width - pad.right + 2}" y="${y(price) - 11}" width="90" height="22" fill="${color}"/><text x="${width - pad.right + 7}" y="${y(price) + 4}" class="chartlabel">${label} ${chartNumber(price)}</text>`;
    const last = candles.at(-1), markers = [line(plan.targetPrice, "TARGET", "#155f46", "5 4"), line(plan.plannedEntry, "ENTRY", "#17201d", "5 4"), line(plan.stopPrice, "STOP", "#a83d35", "5 4")];
    if (Number.isFinite(plan.receipt?.marketPrice)) markers.push(line(plan.receipt.marketPrice, "FILL", "#7253a6"));
    if (Number.isFinite(plan.receipt?.exitPrice)) markers.push(line(plan.receipt.exitPrice, "EXIT", "#b26a16"));
    target.innerHTML = `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtml(plan.symbol)} candlestick chart with paper trade levels"><rect width="${width}" height="${height}" fill="#fffdf7"/>${grid}${bars}${markers.join("")}<text x="${pad.left}" y="${height - 10}" class="chartaxis">${new Date(candles[0].time).toLocaleString()}</text><text x="${width - pad.right}" y="${height - 10}" text-anchor="end" class="chartaxis">${new Date(last.time).toLocaleString()}</text></svg>`;
    const movement = plan.receipt?.marketPrice ? (plan.side === "Long" ? last.close - plan.receipt.marketPrice : plan.receipt.marketPrice - last.close) : null;
    summary.innerHTML = `<div><small>LIVE PRICE</small><b>${chartNumber(last.close)}</b></div><div><small>STATUS</small><b>${escapeHtml(planStatus(plan))}</b></div><div><small>PAPER FILL</small><b>${plan.receipt ? chartNumber(plan.receipt.marketPrice) : "Awaiting approval"}</b></div><div><small>MOVE SINCE FILL</small><b class="${movement == null ? "" : movement >= 0 ? "good" : "bad"}">${movement == null ? "Not open" : `${movement >= 0 ? "+" : ""}${chartNumber(movement)}`}</b></div>`;
  } catch (error) { target.innerHTML = `<div class="chartloading"><b>Chart unavailable</b><span>${escapeHtml(error.message)}</span></div>`; }
}

function renderJournal() {
  $("#recordCount").textContent = `${trades.length} ${trades.length === 1 ? "record" : "records"}`;
  if (!trades.length) { $("#history").innerHTML = '<div class="empty"><div><b>No records yet</b>Your first real trade will appear here after you save it.</div></div>'; $("#review").hidden = true; return; }
  const average = Math.round(trades.reduce((sum, trade) => sum + score(trade), 0) / trades.length);
  $("#history").innerHTML = `<div class="stats"><div class="stat"><small>Trades</small><strong>${trades.length}</strong></div><div class="stat"><small>Average process</small><strong>${average}</strong></div><div class="stat"><small>Rule adherence</small><strong>${rate("followed")}%</strong></div></div><div class="list">${trades.map(trade => `<article class="trade ${trade.id === selectedId ? "selected" : ""}" data-id="${escapeHtml(trade.id)}"><div><b>${escapeHtml(trade.symbol)} / ${escapeHtml(trade.side)}</b><div class="meta">${new Date(trade.created).toLocaleString()} / ${escapeHtml(verdict(trade))}</div></div><div class="score ${score(trade) >= 75 ? "good" : "bad"}">${score(trade)}</div></article>`).join("")}</div>`;
  $("#history").onclick = event => { const item = event.target.closest("[data-id]"); if (item) selectTrade(item.dataset.id); };
  selectTrade(selectedId && trades.some(trade => trade.id === selectedId) ? selectedId : trades[0].id);
}
function selectTrade(id) {
  selectedId = id; const trade = trades.find(item => item.id === id); if (!trade) return;
  $$(".trade").forEach(item => item.classList.toggle("selected", item.dataset.id === id));
  const confirmationMisses = trades.filter(item => !item.confirm).length;
  $("#review").hidden = false;
  $("#review").innerHTML = `<article><h3>Recorded thesis</h3><blockquote>“${escapeHtml(trade.thesis)}”</blockquote><p class="note">Invalidation: ${escapeHtml(trade.invalidation)}</p><button class="deleteRecord" type="button">Delete record</button></article><article><h3>Decision and outcome</h3><p><b>${escapeHtml(verdict(trade))}</b></p><p class="${pnl(trade) >= 0 ? "good" : "danger"}">${pnl(trade).toFixed(2)}% outcome</p><p class="note">${score(trade)}/100 process score. The score never uses profit or loss.</p></article><article class="signal"><h3>Pattern signal</h3><p><b>${confirmationMisses} of ${trades.length}</b></p><p>${confirmationMisses ? "trades were entered without the planned confirmation. This is a direct rule to test next." : "No confirmation violations are recorded yet."}</p></article><article id="processReview"><h3>Process review</h3><p class="note">Reviewing only the decision record, without prices or profit and loss.</p></article>`;
  $(".deleteRecord").onclick = async () => { if (!confirm("Delete this journal record? This cannot be undone.")) return; await localDelete(trade.id); if (cloudClient && cloudSession) { const { error } = await cloudClient.from("trades").delete().eq("id", trade.id); if (error) return alert(error.message); } trades = await readAll(); selectedId = null; reviewCache.delete(trade.id); renderAll(); track("trade_deleted"); };
  reviewTrade(trade);
}
function renderProcessReview(review) { $("#processReview").innerHTML = `<h3>Process review</h3><p>${escapeHtml(review.diagnosis)}</p><p><b>Strengths</b><br>${(review.strengths || []).map(escapeHtml).join(" / ") || "None identified"}</p><p><b>Next rule</b><br>${escapeHtml(review.nextRule)}</p><p class="note">Confidence: ${escapeHtml(review.confidence)}. Educational process coaching only.</p>`; }
async function reviewTrade(trade) {
  if (reviewCache.has(trade.id)) return renderProcessReview(reviewCache.get(trade.id));
  try { const response = await fetch("/api/review", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ trade: { symbol: trade.symbol, side: trade.side, thesis: trade.thesis, invalidation: trade.invalidation, risk: trade.risk, evidence: trade.evidence, confirm: trade.confirm, followed: trade.followed, processScore: score(trade), plan: trade.plan }, historySummary: { tradeCount: trades.length, confirmationMisses: trades.filter(item => !item.confirm).length, ruleAdherencePercent: rate("followed"), averageProcessScore: Math.round(trades.reduce((sum, item) => sum + score(item), 0) / trades.length) } }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Review unavailable"); reviewCache.set(trade.id, data.review); renderProcessReview(data.review); }
  catch (error) { $("#processReview").innerHTML = `<h3>Process review</h3><p class="danger">${escapeHtml(error.message)}</p><p class="note">Your saved record remains available.</p>`; }
}

function renderPatterns() {
  if (!trades.length) { $("#patternsContent").innerHTML = '<section class="card empty"><div><b>No patterns yet</b>Add real trade records in the Journal to calculate your process patterns.</div></section>'; return; }
  const average = Math.round(trades.reduce((sum, trade) => sum + score(trade), 0) / trades.length), wins = trades.filter(trade => pnl(trade) > 0).length;
  const checks = [{ key: "risk", label: "Risk defined" }, { key: "evidence", label: "Opposing evidence" }, { key: "confirm", label: "Confirmation respected" }, { key: "followed", label: "Exit rule followed" }];
  const cells = [{ label: "Good decision / good outcome", count: trades.filter(t => score(t) >= 75 && pnl(t) > 0).length }, { label: "Good decision / adverse outcome", count: trades.filter(t => score(t) >= 75 && pnl(t) <= 0).length }, { label: "Weak decision / favorable outcome", count: trades.filter(t => score(t) < 75 && pnl(t) > 0).length }, { label: "Weak decision / adverse outcome", count: trades.filter(t => score(t) < 75 && pnl(t) <= 0).length }];
  $("#patternsContent").innerHTML = `<section class="patternstats"><div class="stat"><small>Real records</small><strong>${trades.length}</strong></div><div class="stat"><small>Average process</small><strong>${average}</strong></div><div class="stat"><small>Rule adherence</small><strong>${rate("followed")}%</strong></div><div class="stat"><small>Positive outcomes</small><strong>${Math.round(wins / trades.length * 100)}%</strong></div></section><div class="patternbody"><section class="card"><div class="cardhead"><h2>Commitment consistency</h2><span>All records</span></div><div class="bars">${checks.map(item => `<div><div class="barlabel"><span>${item.label}</span><span>${rate(item.key)}%</span></div><div class="bartrack"><div class="barfill" style="width:${rate(item.key)}%"></div></div></div>`).join("")}</div></section><section class="card"><div class="cardhead"><h2>Decision outcome matrix</h2><span>Luck stays visible</span></div><div class="matrix">${cells.map(cell => `<div><b>${cell.count}</b><span>${cell.label}</span></div>`).join("")}</div></section></div>`;
}
function loadRules() { try { return JSON.parse(localStorage.getItem(RULES_KEY) || "[]"); } catch { return []; } }
function loadPolicy() { try { return { mode: "paper", maxCapital: 1000, dailyLoss: 50, maxOrder: 200, maxLeverage: 1, ...JSON.parse(localStorage.getItem(POLICY_KEY) || "{}") }; } catch { return { mode: "paper", maxCapital: 1000, dailyLoss: 50, maxOrder: 200, maxLeverage: 1 }; } }
function renderAgent() {
  const form = $("#riskForm"); if (!form) return;
  form.elements.mode.value = agentPolicy.mode; form.elements.maxCapital.value = agentPolicy.maxCapital; form.elements.dailyLoss.value = agentPolicy.dailyLoss; form.elements.maxOrder.value = agentPolicy.maxOrder; form.elements.maxLeverage.value = agentPolicy.maxLeverage;
  $("#agentModeLabel").textContent = agentPolicy.mode === "paper" ? "Paper only" : agentPolicy.mode === "readonly" ? "Read only" : "Live blocked";
  const receipts = plans.filter(plan => plan.receipt).map(plan => plan.receipt).sort((a, b) => b.created - a.created); $("#receiptCount").textContent = `${receipts.length} ${receipts.length === 1 ? "receipt" : "receipts"}`;
  $("#receiptList").innerHTML = receipts.length ? `<div class="receiptable">${receipts.map(receipt => `<article><div><b>${escapeHtml(receipt.symbol)} / ${escapeHtml(receipt.side)}</b><span>${new Date(receipt.created).toLocaleString()}</span></div><div><b>${receipt.notional} USDT</b><span>Paper fill ${receipt.marketPrice}</span></div><div><b>${receipt.maximumRisk.toFixed(2)} USDT risk</b><span>${receipt.leverage}x / confirmed</span></div><strong>${escapeHtml(receipt.status.toUpperCase())}</strong></article>`).join("")}</div>` : '<div class="empty receipt-empty"><div><b>No execution receipts yet</b>Approved paper orders will appear here with their market snapshot and risk decision.</div></div>';
}
function storeRules() { localStorage.setItem(RULES_KEY, JSON.stringify(rules)); renderRules(); }
function renderRules() { $("#ruleCount").textContent = `${rules.length} ${rules.length === 1 ? "rule" : "rules"}`; $("#ruleList").innerHTML = rules.length ? `<div class="rules">${rules.map(rule => `<article class="rule ${rule.done ? "done" : ""}" data-rule="${rule.id}"><input type="checkbox" ${rule.done ? "checked" : ""} aria-label="Mark rule reviewed"><p>${escapeHtml(rule.text)}</p><button type="button" aria-label="Delete rule">Delete</button></article>`).join("")}</div>` : '<div class="empty"><div><b>No rules yet</b>Add one observable rule you can check before the next trade.</div></div>'; renderPlanRuleOptions(); }

function toCloud(trade, userId) { return { id: trade.id, user_id: userId, plan_id: trade.planId || null, plan_snapshot: trade.plan || null, symbol: trade.symbol, side: trade.side, entry: trade.entry, exit: trade.exit, thesis: trade.thesis, invalidation: trade.invalidation, risk_defined: !!trade.risk, opposing_evidence_recorded: !!trade.evidence, confirmation_waited: !!trade.confirm, exit_rule_followed: !!trade.followed, created_at: new Date(trade.created).toISOString(), updated_at: new Date().toISOString() }; }
function fromCloud(trade) { return { id: trade.id, created: new Date(trade.created_at).getTime(), planId: trade.plan_id || null, plan: trade.plan_snapshot || null, symbol: trade.symbol, side: trade.side, entry: Number(trade.entry), exit: Number(trade.exit), thesis: trade.thesis, invalidation: trade.invalidation, risk: trade.risk_defined, evidence: trade.opposing_evidence_recorded, confirm: trade.confirmation_waited, followed: trade.exit_rule_followed }; }
function setCloudState(message) { $("#cloudState").textContent = message; }
async function syncCloud() { if (!cloudClient || !cloudSession) return; setCloudState("Syncing securely"); const [localTrades, localPlans] = await Promise.all([readAll(), readPlans()]); if (localPlans.length) { const { error } = await cloudClient.from("trade_plans").upsert(localPlans.map(plan => toCloudPlan(plan, cloudSession.user.id))); if (error) throw error; } if (localTrades.length) { const { error } = await cloudClient.from("trades").upsert(localTrades.map(trade => toCloud(trade, cloudSession.user.id))); if (error) throw error; } const [{ data: cloudPlans, error: planError }, { data, error }] = await Promise.all([cloudClient.from("trade_plans").select("*").order("created_at", { ascending: false }), cloudClient.from("trades").select("*").order("created_at", { ascending: false })]); if (planError) throw planError; if (error) throw error; plans = (cloudPlans || []).map(fromCloudPlan); trades = (data || []).map(fromCloud); for (const plan of plans) await localPlanPut(plan); for (const trade of trades) await localPut(trade); renderAll(); setCloudState(`Cloud synced / ${cloudSession.user.email || "signed in"}`); $("#authEmail").hidden = true; $("#authAction").textContent = "Sign out"; }
function setSignedOut() { setCloudState("Local journal / sign in to sync"); $("#authEmail").hidden = false; $("#authAction").textContent = "Sync securely"; }
async function initCloud() { try { const configResponse = await fetch("/api/config"); const config = await configResponse.json(); if (!configResponse.ok || !config.cloudEnabled || !window.supabase) throw new Error("Cloud sync is currently unavailable. Local journal is active."); cloudClient = window.supabase.createClient(config.supabaseUrl, config.publishableKey); const { data } = await cloudClient.auth.getSession(); cloudSession = data.session; if (cloudSession) await syncCloud(); else setSignedOut(); cloudClient.auth.onAuthStateChange((_event, session) => { cloudSession = session; setTimeout(() => session ? syncCloud().catch(error => setCloudState(error.message)) : setSignedOut(), 0); }); } catch (error) { setCloudState(error.message || "Cloud sync is currently unavailable. Local journal is active."); $(".auth").hidden = true; } }
function renderAll() { renderPlans(); renderAgent(); renderJournal(); renderPatterns(); renderRules(); }

$("#planForm").onsubmit = async event => { event.preventDefault(); const form = event.currentTarget, data = new FormData(form), button = form.querySelector("button[type=submit]"); const values = ["plannedEntry", "stopPrice", "targetPrice", "riskPercent"].map(key => Number(data.get(key))); if (values.some(value => !Number.isFinite(value) || value <= 0)) return $("#planError").textContent = "Entry, stop, target, and risk must be greater than zero."; const plan = { id: crypto.randomUUID(), created: Date.now(), status: "planned", symbol: String(data.get("symbol")).trim().toUpperCase(), side: data.get("side"), plannedEntry: values[0], stopPrice: values[1], targetPrice: values[2], riskPercent: values[3], thesis: String(data.get("thesis")).trim(), invalidation: String(data.get("invalidation")).trim(), ruleIds: data.getAll("playbookRule") }; button.disabled = true; try { await savePlan(plan); plans = await readPlans(); selectedPlanId = plan.id; form.reset(); form.elements.riskPercent.value = "1"; renderPlans(); track("plan_locked"); } catch (error) { $("#planError").textContent = error.message || "The plan could not be saved."; } finally { button.disabled = false; } };
$("#form").onsubmit = async event => { event.preventDefault(); const form = event.currentTarget, button = form.querySelector("button[type=submit]"), data = new FormData(form), plan = plans.find(item => item.id === data.get("planId")); const trade = { id: crypto.randomUUID(), created: Date.now(), planId: plan?.id || null, plan: plan ? { created: plan.created, plannedEntry: plan.plannedEntry, stopPrice: plan.stopPrice, targetPrice: plan.targetPrice, riskPercent: plan.riskPercent, ruleIds: plan.ruleIds } : null, symbol: String(data.get("symbol")).trim().toUpperCase(), side: data.get("side"), entry: Number(data.get("entry")), exit: Number(data.get("exit")), thesis: String(data.get("thesis")).trim(), invalidation: String(data.get("invalidation")).trim(), risk: data.has("risk"), evidence: data.has("evidence"), confirm: data.has("confirm"), followed: data.has("followed") }; if (!Number.isFinite(trade.entry) || !Number.isFinite(trade.exit) || trade.entry <= 0 || trade.exit <= 0) { $("#formError").textContent = "Entry and exit prices must be greater than zero."; return; } button.disabled = true; $("#formError").textContent = ""; try { await saveTrade(trade); if (plan) { plan.status = "completed"; plan.completedAt = Date.now(); plan.tradeId = trade.id; if (plan.receipt) { plan.receipt.status = "closed"; plan.receipt.exitPrice = trade.exit; plan.receipt.closedAt = plan.completedAt; } await savePlan(plan); plans = await readPlans(); } trades = await readAll(); selectedId = trade.id; form.reset(); renderAll(); track(plan ? "planned_trade_audited" : "trade_saved"); } catch (error) { $("#formError").textContent = error.message || "The record could not be saved."; } finally { button.disabled = false; } };
$("#ruleForm").onsubmit = event => { event.preventDefault(); const text = String(new FormData(event.currentTarget).get("text")).trim(); if (!text) return; rules.unshift({ id: crypto.randomUUID(), text, done: false }); event.currentTarget.reset(); storeRules(); track("rule_added"); };
$("#riskForm").onsubmit = event => { event.preventDefault(); const data = new FormData(event.currentTarget), next = { mode: String(data.get("mode")), maxCapital: Number(data.get("maxCapital")), dailyLoss: Number(data.get("dailyLoss")), maxOrder: Number(data.get("maxOrder")), maxLeverage: Number(data.get("maxLeverage")) }; if (Object.values(next).slice(1).some(value => !Number.isFinite(value) || value <= 0)) return; if (next.maxOrder > next.maxCapital) return alert("Maximum order cannot exceed allocated capital."); if (next.mode === "live") { next.mode = "paper"; alert("Live mode remains blocked until Bitget Agentic Account OAuth is connected. Paper mode was kept active."); } agentPolicy = next; localStorage.setItem(POLICY_KEY, JSON.stringify(agentPolicy)); renderAgent(); track("risk_policy_updated"); };
$("#ruleList").onclick = event => { const item = event.target.closest("[data-rule]"); if (!item) return; const id = item.dataset.rule; if (event.target.matches("button")) rules = rules.filter(rule => rule.id !== id); else if (event.target.matches("input")) rules = rules.map(rule => rule.id === id ? { ...rule, done: event.target.checked } : rule); storeRules(); };
$("#export").onclick = () => { const blob = new Blob([JSON.stringify({ exportedAt: new Date().toISOString(), trades, rules }, null, 2)], { type: "application/json" }), link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = "processalpha-export.json"; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 0); };
$$('[data-view]').forEach(button => button.onclick = () => { showView(button.dataset.view); if (button.dataset.view === "patterns") renderPatterns(); if (button.dataset.view === "plan") renderPlans(); if (button.dataset.view === "agent") renderAgent(); track("view_changed", { view: button.dataset.view }); });
$("#authAction").onclick = async () => { if (!cloudClient) return setCloudState("Cloud sync is currently unavailable"); if (cloudSession) return cloudClient.auth.signOut(); const email = $("#authEmail").value.trim(); if (!email) return setCloudState("Enter your email address"); $("#authAction").disabled = true; setCloudState("Sending secure sign in link"); const { error } = await cloudClient.auth.signInWithOtp({ email, options: { emailRedirectTo: `${location.origin}/app` } }); $("#authAction").disabled = false; setCloudState(error ? error.message : "Check your email for the secure sign in link"); };

addEventListener("error", () => track("client_error"));
addEventListener("unhandledrejection", () => track("client_error"));
(async () => { track("workspace_opened", { view: "plan" }); try { [trades, plans] = await Promise.all([readAll(), readPlans()]); renderAll(); } catch { $("#history").innerHTML = '<div class="empty"><div><b>Storage unavailable</b>Enable browser storage before saving a record.</div></div>'; } initCloud(); })();
